#include "stdlib/blas/base/dtrmv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x`, where `x` is an `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* @param layout    storage layout
* @param uplo      specifies whether `A` is an upper or lower triangular matrix
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag      specifies whether `A` has a unit diagonal
* @param N         number of elements along each dimension of `A`
* @param A         input matrix
* @param LDA       stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param x         input vector
* @param strideX   `x` stride length
* @return          output value
*/
void API_SUFFIX(c_dtrmv)( const CBLAS_LAYOUT layout, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE trans, const CBLAS_DIAG diag, const CBLAS_INT N, const double *A, const CBLAS_INT LDA, double *x, const CBLAS_INT strideX ) {
	CBLAS_INT vala;
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT ox;

	// Perform input argument validation...
	if ( layout != CblasRowMajor && layout != CblasColMajor ) {
		c_xerbla( 1, "c_dtrmv", "Error: invalid argument. First argument must be a valid layout. Value: `%d`.", layout );
		return;
	}
	if ( uplo != CblasLower && uplo != CblasUpper ) {
		c_xerbla( 2, "c_dtrmv", "Error: invalid argument. Second argument must specify whether the lower or upper triangular matrix is supplied. Value: `%d`.", uplo );
		return;
	}
	if ( trans != CblasTrans && trans != CblasConjTrans && trans != CblasNoTrans ) {
		c_xerbla( 3, "c_dtrmv", "Error: invalid argument. Third argument must be a valid transpose operation. Value: `%d`.", trans );
		return;
	}
	if ( diag != CblasNonUnit && diag != CblasUnit ) {
		c_xerbla( 4, "c_dtrmv", "Error: invalid argument. Fourth argument must be a valid diagonal type. Value: `%d`.", diag );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 5, "c_dtrmv", "Error: invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	// max(1, N)
	if ( N < 1 ) {
		vala = 1;
	} else {
		vala = N;
	}
	if ( LDA < vala ) {
		c_xerbla( 7, "c_dtrmv", "Error: invalid argument. Seventh argument must be greater than or equal to max(1,%d). Value: `%d`.", vala, LDA );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 9, "c_dtrmv", "Error: invalid argument. Ninth argument must be a nonzero. Value: `%d`.", strideX );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( N == 0 ) {
		return;
	}
	if ( layout == CblasColMajor ) {
		sa1 = 1;
		sa2 = LDA;
	} else { // layout === CblasRowMajor
		sa1 = LDA;
		sa2 = 1;
	}
	ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(c_dtrmv_ndarray)( uplo, trans, diag, N, A, sa1, sa2, 0, x, strideX, ox );
	return;
}
